  private:
    static Json::Value vectorToJson(subs subsVector) {
      Json::Value outer(Json::arrayValue);
      for (std::vector<std::string> sub : subsVector) {
        Json::Value inner(Json::arrayValue);
        for (std::string el : sub) {
          inner.append(el);
        }
        outer.append(inner);
      }
      return outer;
    }

    static std::string join(std::vector<std::string> vec) {
      if (vec.empty()) {
        return "";
      }

      return std::accumulate(
        std::next(vec.begin()), 
        vec.end(), 
        vec[0], 
        [](std::string a, std::string b) {
            return a + ',' + b;
        }
      );
