## solutions

#### recursive

```cpp
#include <vector>
#include <string>

std::vector<std::vector<std::string>> subsets(std::vector<std::string> elements) {
  if (elements.size() == 0) {
    return std::vector<std::vector<std::string>> {{}};
  }

  std::string el = elements[0];
  std::vector<std::vector<std::string>> subsWithout = subsets(std::vector<std::string>(elements.begin() + 1, elements.end()));

  std::vector<std::vector<std::string>> result;
  for (std::vector<std::string> without : subsWithout) {
    result.push_back(without);

    std::vector<std::string> with = std::vector<std::string>(without.begin(), without.end());
    with.push_back(el);
    result.push_back(with);  
  }

  return result;
}
```

- n = length of elements vector
- Time: ~O(2^n)
- Space: ~O(2^n)
